@Component("screening-handler")
@ProcessingGroup("screening-processing-group")
public class ScreeningEventHandler {
	
	// core constructor
	ScreeningEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateScreeningEvent
     */
    @EventHandler
    public void handle( CreateScreeningEvent event) {
        entityManager.persist(new Screening(event.getScreeningId(), event.getScore(), event.getScreenedAt(), event.getKycProfile(), event.getAlerts(), event.getScreeningType(), event.getStatus()));
    }

    /*
     * @param	event UpdateScreeningEvent
     */
    @EventHandler
    public Screening handle( UpdateScreeningEvent event) {
    	entityManager.merge(new Screening(event.getScreeningId(), event.getScore(), event.getScreenedAt(), event.getKycProfile(), event.getAlerts(), event.getScreeningType(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteScreeningEvent
     */
    @EventHandler
    public void on( DeleteScreeningEvent event) {
    	Screening entity = new Screening();
   
    	// ------------------------------------------
    	// apply the ScreeningId
    	// ------------------------------------------
    	entity.setScreeningId( event.getScreeningId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ScreeningRepository screeningEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ScreeningEventHandler.class.getName());

}
